contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We take callee and data as arbitrary inputs. We also take sendAmount but
    // must ensure not to send Ether to a non-payable function: C.forward is non-payable,
    // so we require sendAmount == 0 and make a plain call.
    function run(address callee, bytes calldata data, uint sendAmount) public payable {
        require(sendAmount == 0);
        // record balance before
        uint balBefore = address(c).balance;
        bool reverted;
        // perform the state-changing call on c; must be top-level
        c.forward(callee, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        uint balAfter = address(c).balance;
        // If the call returned (did not revert) then c's balance is unchanged.
        assert(reverted || balAfter == balBefore);
    }

    receive() external payable {}
}

