pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Proxy c;

    function setUp() public {
        c = new Proxy();
    }

    function _run(address callee, bytes memory data, uint256 sendAmount) internal {
        sendAmount = 0;
        uint balBefore = address(c).balance;
        bool reverted;
        try c.forward(callee, data) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint balAfter = address(c).balance;
        assertTrue(reverted || balAfter == balBefore);
    }

    function testFuzz_run(address callee, bytes memory data, uint256 sendAmount) public {
